    for src_name,src in [("a",a),("b",b),("ar",a[::-1]),("br",b[::-1])]:
        for k,rot in enumerate(rotations(src)):
            if t==rot: print(name,"=",src_name,"rot",k)
            if t==rot[::-1]: print(name,"= rev of",src_name,"rot",k)
