for name,t in [("t0",target0),("t1",target1)]:
    for k,rot in enumerate(rotations(inter)+rotations(inter2)):
        if t==rot: print(name,"= interleave rot",k)
        if t==rot[::-1]: print(name,"= rev interleave rot",k)
